/// Full lowercase mapping (UnicodeData simple + unconditional SpecialCasing),
/// or null when the code point has no lowercase mapping.
pub fn lowerOf(cp: u21) ?LowerTarget {
    var lo: usize = 0;
    var hi: usize = lower_entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = lower_entries[mid];
        if (e.cp == cp) return e.t;
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return null;
}

