/// Fullwidth or halfwidth code point (East_Asian_Width F or H per
/// UAX #11) mapped to its decomposition mapping, per the RFC 8265
/// width mapping rule, or null when the code point is not mapped.
pub fn widthOf(cp: u21) ?u21 {
    var lo: usize = 0;
    var hi: usize = width_entries.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = width_entries[mid];
        if (e.cp == cp) return e.to;
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return null;
}

