/// Arabic joining type (RFC 8265 Appendix A.1); default is `none`.
pub fn joinTypeOf(cp: u21) JoinType {
    var lo: usize = 0;
    var hi: usize = join_ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = join_ranges[mid];
        if (cp < r.start) hi = mid else if (cp > r.end) lo = mid + 1 else return r.jt;
    }
    return .none;
}

