/// Bidi_Class group for the RFC 5893 Bidi Rule (RFC 8264 section 8.2).
pub fn bidiGroupOf(cp: u21) BidiGroup {
    if (cp >= 0x110000) return .other;
    const i: u32 = cp;
    const g = i / 8 * 3; // 8 code points per 3-byte group (3 bits each)
    const o: u5 = @intCast((i % 8) * 3);
    const v: u32 = bidi_bits[g] | @as(u32, bidi_bits[g + 1]) << 8 | @as(u32, bidi_bits[g + 2]) << 16;
    return @enumFromInt(@as(u3, @intCast((v >> o) & 7)));
}

