/// Script group used by the CONTEXTJ/CONTEXTO rules.
pub fn scriptGroupOf(cp: u21) ScriptGroup {
    if (cp >= 0x110000) return .other;
    const i: u32 = cp;
    return @enumFromInt((script_bits[i >> 2] >> @intCast((i & 3) * 2)) & 3);
}

